3	/**
4	 * Single source of truth for the owner telephone normalization rule, shared by the
5	 * owner-create pipeline. The uniqueness check only holds if both the value stored for a
6	 * new owner and the values compared against existing owners are normalized identically,
7	 * so that rule lives here rather than being duplicated across steps.
8	 */
9	final class OwnerTelephone {
10	
11	    private OwnerTelephone() {
12	    }
13	
14	    /**
15	     * Normalize a telephone to E.164 form, or {@code null} if the input is {@code null} or
16	     * cannot form a valid E.164 number.
17	     *
18	     * <p>Spaces, dashes and brackets are stripped. A leading {@code '+'} and country code are
19	     * kept when present; otherwise the country code {@code '+61'} is assumed and a single
20	     * leading {@code '0'} is dropped from the national digits. The result is valid only when
21	     * it has 8 to 15 digits after the {@code '+'}; anything else (including stray non-digit
22	     * characters) yields {@code null}. The function is idempotent: an already-E.164 value
23	     * normalizes to itself.
24	     */
25	    static String normalize(String telephone) {
26	        if (telephone == null) {
27	            return null;
28	        }
29	        String cleaned = telephone.replaceAll("[\\s()-]", "");
30	        boolean hasPlus = cleaned.startsWith("+");
31	        String digits = hasPlus ? cleaned.substring(1) : cleaned;
32	        if (!digits.matches("[0-9]+")) {
33	            return null;
34	        }
35	        String e164Digits;
36	        if (hasPlus) {
37	            e164Digits = digits;
38	        }
39	        else {
40	            String national = digits.startsWith("0") ? digits.substring(1) : digits;
41	            e164Digits = "61" + national;
42	        }
43	        if (e164Digits.length() < 8 || e164Digits.length() > 15) {
44	            return null;
45	        }
46	        return "+" + e164Digits;
47	    }
48	}
