27	     * letters of the last name and NNNN is a global 4-digit zero-padded sequence equal
28	     * to one more than the current number of owners (e.g. 'SMI-0007').
29	     */
30	    private static String nextCustomerCode(String lastName, OwnerRepository ownerRepository) {
31	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
32	        int sequence = ownerRepository.findAll().size() + 1;
33	        return String.format("%s-%04d", last3, sequence);
34	    }
35	}
