3	import java.util.regex.Pattern;
4	
5	/**
6	 * Single source of truth for the owner email rule, shared by the owner pipelines. An
7	 * owner may omit the email, but when supplied it must be a syntactically valid address
8	 * and is stored and returned lower-cased. Keeping the validity check and the
9	 * lower-casing here keeps the create and update paths consistent.
10	 */
11	final class OwnerEmail {
12	
13	    /**
14	     * Pragmatic syntactic check for a single address: a non-empty local part, an
15	     * {@code @}, then a domain with at least one dot and no whitespace. Rejects values
16	     * like {@code not-an-email} that lack an {@code @} and a dotted domain.
17	     */
18	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");
19	
20	    private OwnerEmail() {
21	    }
22	
23	    /** Whether {@code email} is a syntactically valid address. */
24	    static boolean isValid(String email) {
25	        return email != null && EMAIL.matcher(email).matches();
26	    }
27	
28	    /** Lower-case and trim the email, or {@code null} when absent/blank. */
29	    static String normalize(String email) {
30	        if (email == null) {
31	            return null;
32	        }
33	        String trimmed = email.trim();
34	        return trimmed.isEmpty() ? null : trimmed.toLowerCase();
35	    }
36	}
